/**
 * Admin Dashboard Page
 * Premium admin dashboard with analytics and management
 */

import React, { useState, useEffect } from 'react';
import LoadingSpinner from '../components/LoadingSpinner';
import api from '../services/api';
import './AdminDashboard.css';

const AdminDashboard = () => {
  const navigate = useNavigate();
  const [dashboard, setDashboard] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [refreshing, setRefreshing] = useState(false);

  useEffect(() => {
    fetchDashboard();
  }, []);

  const fetchDashboard = async () => {
    try {
      const response = await api.get('/dashboard/admin');
      setDashboard(response.data.dashboard);
      setError('');
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to fetch dashboard');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  const handleRefresh = async () => {
    setRefreshing(true);
    await fetchDashboard();
  };

  if (loading) {
    return <LoadingSpinner message="Loading admin dashboard..." />;
  }

  if (error && !dashboard) {
    return (
      <div className="admin-dashboard-page">
        <div className="admin-container">
          <div className="error-container">
            <h2>⚠️ Error Loading Dashboard</h2>
            <p>{error}</p>
            <button className="refresh-btn" onClick={handleRefresh}>
              🔄 Retry
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="admin-dashboard-page">
      <div className="admin-container">
        <div className="dashboard-header">
          <h1>📊 Admin Dashboard</h1>
          <div className="header-actions">
            <button 
              className="action-btn manage-btn"
              onClick={() => navigate('/admin/manage-events')}
              title="Manage all events"
            >
              📋 Manage Events
            </button>
            <button 
              className="action-btn create-btn"
              onClick={() => navigate('/admin/create-event')}
              title="Create a new event"
            >
              ➕ Create Event
            </button>
            <button 
              className="refresh-btn" 
              onClick={handleRefresh}
              disabled={refreshing}
            >
              🔄 {refreshing ? 'Refreshing...' : 'Refresh'}
            </button>
          </div>
        </div>

        {/* Stats Grid */}
        <div className="stats-grid">
          <div className="stat-card">
            <span className="stat-icon">👥</span>
            <div className="stat-content">
              <h3>Total Users</h3>
              <p className="stat-value">{dashboard?.totalUsers || 0}</p>
            </div>
          </div>

          <div className="stat-card">
            <span className="stat-icon">📅</span>
            <div className="stat-content">
              <h3>Total Events</h3>
              <p className="stat-value">{dashboard?.totalEvents || 0}</p>
            </div>
          </div>

          <div className="stat-card">
            <span className="stat-icon">🎫</span>
            <div className="stat-content">
              <h3>Total Bookings</h3>
              <p className="stat-value">{dashboard?.totalBookings || 0}</p>
            </div>
          </div>

          <div className="stat-card">
            <span className="stat-icon">💰</span>
            <div className="stat-content">
              <h3>Total Revenue</h3>
              <p className="stat-value revenue">₹{dashboard?.totalRevenue || 0}</p>
            </div>
          </div>
        </div>

        {/* Bookings by Status */}
        <div className="chart-section">
          <h2>📈 Bookings by Status</h2>
          <div className="status-overview">
            {Object.entries(dashboard?.bookingsByStatus || {}).map(([status, count]) => (
              <div key={status} className="status-item">
                <span className="status-name">{status}</span>
                <span className="status-count">{count}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Recent Activity - Recent Bookings */}
        <div className="recent-activity-section">
          <h2>📋 Recent Bookings</h2>
          <div className="table-container">
            {dashboard?.recentBookings && dashboard.recentBookings.length > 0 ? (
              <table className="data-table">
                <thead>
                  <tr>
                    <th>User Name</th>
                    <th>Event Name</th>
                    <th>Date</th>
                    <th>Tickets</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {dashboard.recentBookings.slice(0, 10).map((booking, idx) => (
                    <tr key={idx}>
                      <td className="user-cell">
                        <span className="user-name">{booking.userName}</span>
                      </td>
                      <td className="event-cell">{booking.eventName}</td>
                      <td className="date-cell">{new Date(booking.date).toLocaleDateString('en-IN')}</td>
                      <td className="tickets-cell">
                        <span className="ticket-badge">{booking.tickets}</span>
                      </td>
                      <td className="status-cell">
                        <span className={`status-badge ${booking.status?.toLowerCase() || 'confirmed'}`}>
                          {booking.status || 'Confirmed'}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : (
              <div className="empty-state">📭 No recent bookings</div>
            )}
          </div>
        </div>

        {/* Top Events */}
        <div className="recent-activity-section">
          <h2>⭐ Top Events</h2>
          <div className="table-container">
            {dashboard?.topEvents && dashboard.topEvents.length > 0 ? (
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Event Name</th>
                    <th>Total Bookings</th>
                    <th>Revenue</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {dashboard.topEvents.slice(0, 10).map((event, idx) => (
                    <tr key={idx} className={idx === 0 ? 'top-highlight' : ''}>
                      <td className="event-name-cell">
                        {idx === 0 && '🏆 '}
                        <span className="event-name">{event.eventName}</span>
                      </td>
                      <td className="bookings-cell">
                        <span className="bookings-badge">{event.bookings}</span>
                      </td>
                      <td className="revenue-cell">₹{event.revenue}</td>
                      <td className="status-cell">
                        <span className={`status-badge ${event.bookings > 50 ? 'sold-out' : 'active'}`}>
                          {event.bookings > 50 ? 'Sold Out' : 'Active'}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : (
              <div className="empty-state">📭 No events data</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
